//go:build ignore

// Read-only inventory of archived personal course observations.
package main
import("context";"encoding/json";"fmt";"os";"time";"github.com/jackc/pgx/v5")
func main(){ctx,cancel:=context.WithTimeout(context.Background(),20*time.Second);defer cancel();cfg,e:=pgx.ParseConfig(os.Getenv("DATABASE_URL"));if e!=nil{panic("config")};cfg.RuntimeParams["default_transaction_read_only"]="on";c,e:=pgx.ConnectConfig(ctx,cfg);if e!=nil{panic("database")};defer c.Close(ctx);owner:=os.Getenv("COURSE_AUDIT_OWNER");if owner==""{panic("owner required")};queries:=map[string]string{
"raw_course_counts":`SELECT row_to_json(x) FROM(SELECT p.source,count(*) records,min(p.observed_at) oldest_observation,max(p.observed_at) newest_observation FROM platform_records p JOIN platform_connections c ON c.user_id=p.user_id AND c.id=p.connection_id WHERE p.user_id=$1 AND p.kind='course' AND c.enabled AND c.state='active' GROUP BY p.source ORDER BY p.source)x`,
"structured_course_counts":`SELECT row_to_json(x) FROM(SELECT a.source,count(*) offerings,min(a.observed_at) oldest_observation,max(a.observed_at) newest_observation FROM academic_offerings a JOIN platform_connections c ON c.user_id=a.user_id AND c.id=a.connection_id WHERE a.user_id=$1 AND c.enabled AND c.state='active' GROUP BY a.source ORDER BY a.source)x`,
"structured_courses":`SELECT row_to_json(x) FROM(SELECT a.source,a.name,a.teacher,a.course_type,a.native_course_id,a.native_class_id,a.native_term_id,a.observed_at FROM academic_offerings a JOIN platform_connections c ON c.user_id=a.user_id AND c.id=a.connection_id WHERE a.user_id=$1 AND c.enabled AND c.state='active' ORDER BY a.source,a.name)x`,
"jwxt_saved_records":`SELECT row_to_json(x) FROM(SELECT source,kind,count(*) records FROM platform_records WHERE user_id=$1 AND source='jwxt' GROUP BY source,kind)x`,
};out:=map[string]any{"read_only":true,"source_collection_started":false,"checked_at":time.Now().UTC()};for name,q:=range queries{rows,e:=c.Query(ctx,q,owner);if e!=nil{panic("query "+name)};values:=[]json.RawMessage{};for rows.Next(){var raw []byte;if e=rows.Scan(&raw);e!=nil{panic("scan")};values=append(values,raw)};rows.Close();if rows.Err()!=nil{panic("rows")};out[name]=values};raw,_:=json.MarshalIndent(out,"","  ");if e=os.WriteFile("../.build/course-availability-20261117.private.json",raw,0600);e!=nil{panic("save")};fmt.Println(string(raw))}
